/**
 * Pre-aggregated time series loader.
 *
 * Instead of fetching all 72 .bin files and aggregating client-side (which
 * downloads 280MB+ per dataset), this loader fetches a small pre-computed
 * JSON file (~2KB) that contains the global aggregation for each time step.
 *
 * The JSON files are generated by scripts/precompute-timeseries.py and
 * stored inside the GitHub Release ZIPs alongside the .bin files.
 *
 * Fallback: if the pre-aggregated JSON is not available, falls back to
 * the client-side aggregation in data-adapter.ts.
 */

import { fetchReleaseJson } from './release-json';
import type { VariableConfig, TimeSeriesPoint } from '../analytics/types';

/** In-memory cache for pre-aggregated time series JSON. */
const tsCache = new Map<string, TimeSeriesPoint[] | null>();

/**
 * Try to load a pre-aggregated time series from the ZIP.
 * Returns null if not available (falls back to client-side aggregation).
 *
 * The JSON file is stored as `<datasetId>-timeseries.json` inside the ZIP.
 */
export async function tryGetPreAggregatedSeries(
  config: VariableConfig,
): Promise<TimeSeriesPoint[] | null> {
  const cacheKey = `${config.datasetId}:${config.datasetVariableId}`;
  const cached = tsCache.get(cacheKey);
  if (cached !== undefined) return cached;

  // The timeseries JSON is stored inside the ZIP as a .json file.
  // Path: /release-data/<dir>/<datasetId>-timeseries.json
  const dirMap: Record<string, string> = {
    sst: 'sst',
    mhw: 'mhw',
    ph_surface: 'ph',
    ph_trend: 'ph',
    sea_level: 'sea-level',
    sea_ice_arctic: 'sea-ice',
    sea_ice_antarctic: 'sea-ice',
  };
  const dir = dirMap[config.datasetId] ?? config.datasetId;
  const tsPath = `/release-data/${dir}/${config.datasetId}-timeseries.json`;

  try {
    const json = await fetchReleaseJson(tsPath);
    if (json && json.points) {
      const points: TimeSeriesPoint[] = json.points.map((p: any) => ({
        date: p.date,
        year: p.year,
        month: p.month,
        value: p.value ?? NaN,
      }));
      tsCache.set(cacheKey, points);
      console.log(`[timeseries] Loaded pre-aggregated ${config.datasetId}: ${points.length} points`);
      return points;
    }
  } catch {
    // Pre-aggregated JSON not available — fall back
  }

  tsCache.set(cacheKey, null);
  return null;
}
